function seed(input: Seed): Company {
  return {
    id: input.id,
    nameEn: input.nameEn,
    nameZh: input.nameZh,
    ticker: input.ticker,
    exchange: input.exchange,
    market: input.market,
    country: input.country,
    listed: input.market !== 'Private',
    primaryLayer: input.primaryLayer,
    primaryTheme: input.primaryTheme,
    segment: input.segment,
    tagZh: input.tagZh,
    tagEn: input.tagEn,
    themeExposures: [
      {
        themeId: input.themeId,
        layerId: input.primaryLayer,
        relevance: input.relevance,
        purity: input.purity,
        revenueExposure: input.revenueExposure,
        capexSensitivity: input.capex,
        positionType: input.positionType ?? (input.market === 'Private' ? 'private-company' : 'direct-business'),
        evidence: input.tagZh,
      },
      ...(input.extra ?? []),
    ],
    relatedPrivateCompanies: input.relatedPrivateCompanies,
    relatedListedCompanies: input.relatedListedCompanies,
    aiRelevanceScore: input.ai,
    revenueElasticityScore: input.elasticity,
    capexLinkageScore: input.capex,
    purityScore: input.purity,
    price: input.price,
    marketCapUsdBn: input.marketCap,
    weekChangePct: input.week,
    retailHeatScore: input.retailHeat,
    mainFundFlowScore: input.mainFund,
    dataCenterCapacityGw: input.dataCenterCapacityGw,
    gpuEquivalentK: input.gpuEquivalentK,
    modelBenchmarks: input.modelBenchmarks,
    valuationSourceUrl: input.valuationSourceUrl,
    quoteUrl: input.quoteUrl,
    newsSearchUrl: input.newsSearchUrl,
    valuationMetric: input.metric,
    valuationValue: input.value,
    valuationScore: input.score,
    valuationLabel: input.label,
    nextEarningsDate: input.earnings,
    earningsConfirmed: Boolean(input.earnings),
    riskFlags: input.risks ?? [],
    dataQuality: input.dataQuality ?? (input.market === 'Private' || input.positionType === 'private-company' ? 'estimated' : 'seed'),
    updatedAt,
  }
}

